insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (41, 'draft', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'せんせいを <u>呼びます</u>。', '["よびます","とりかえます","あずかります","たすけます"]'::jsonb, 0, '呼びます dibaca “よびます” dan berarti memanggil.', 'Bab 41–45 · Mondai 1 No.1', 'kanji:呼びます'),
  (41, 'draft', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'くつしたを <u>取り替えます</u>。', '["とりかえます","よびます","あずかります","くらします"]'::jsonb, 0, '取り替えます dibaca “とりかえます” dan berarti mengganti.', 'Bab 41–45 · Mondai 1 No.2', 'kanji:取り替えます'),
  (41, 'draft', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にもつを <u>預かります</u>。', '["あずかります","たすかります","たすけます","くらします"]'::jsonb, 0, '預かります dibaca “あずかります” dan berarti menjagakan/menerima titipan.', 'Bab 41–45 · Mondai 1 No.3', 'kanji:預かります'),
  (41, 'draft', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'おくりものを <u>包みます</u>。', '["つつみます","まぜます","わかします","けいさんします"]'::jsonb, 0, '包みます dibaca “つつみます” dan berarti membungkus.', 'Bab 41–45 · Mondai 1 No.4', 'kanji:包みます'),
  (41, 'draft', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'おゆを <u>沸かします</u>。', '["わかします","つつみます","まぜます","けいさんします"]'::jsonb, 0, '沸かします dibaca “わかします” dan berarti merebus/memanaskan air.', 'Bab 41–45 · Mondai 1 No.5', 'kanji:沸かします'),
  (41, 'draft', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'かいいんが <u>増えます</u>。', '["ふえます","へります","あがります","さがります"]'::jsonb, 0, '増えます dibaca “ふえます” dan berarti meningkat/bertambah.', 'Bab 41–45 · Mondai 1 No.6', 'kanji:増えます'),
  (41, 'draft', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'やまから いしが <u>落ちます</u>。', '["おちます","きれます","さがります","へります"]'::jsonb, 0, '落ちます dibaca “おちます” dan berarti jatuh.', 'Bab 41–45 · Mondai 1 No.7', 'kanji:落ちます'),
  (41, 'draft', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもが <u>笑います</u>。', '["わらいます","なきます","かわきます","すべります"]'::jsonb, 0, '笑います dibaca “わらいます” dan berarti tertawa.', 'Bab 41–45 · Mondai 1 No.8', 'kanji:笑います'),
  (41, 'draft', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ともだちに <u>謝ります</u>。', '["あやまります","しんじます","よういします","ねむります"]'::jsonb, 0, '謝ります dibaca “あやまります” dan berarti meminta maaf.', 'Bab 41–45 · Mondai 1 No.9', 'kanji:謝ります'),
  (41, 'draft', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'よる はやく <u>眠ります</u>。', '["ねむります","あやまります","しんじます","なります"]'::jsonb, 0, '眠ります dibaca “ねむります” dan berarti tidur.', 'Bab 41–45 · Mondai 1 No.10', 'kanji:眠ります'),
  (41, 'draft', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にほんの れきしに <u>きょうみ</u>が あります。', '["興味","情報","文法","発音"]'::jsonb, 0, 'きょうみ ditulis 興味, berarti minat.', 'Bab 41–45 · Mondai 2 No.11', 'kanji:興味'),
  (41, 'draft', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ニュースで <u>じょうほう</u>を ききます。', '["情報","興味","文法","発音"]'::jsonb, 0, 'じょうほう ditulis 情報, berarti informasi.', 'Bab 41–45 · Mondai 2 No.12', 'kanji:情報'),
  (41, 'draft', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんたくで <u>けいさんします</u>。', '["計算します","確認します","用意します","優勝します"]'::jsonb, 0, 'けいさんします ditulis 計算します, berarti menghitung.', 'Bab 41–45 · Mondai 2 No.13', 'kanji:計算します'),
  (41, 'draft', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にほんの <u>れきし</u>を べんきょうします。', '["歴史","文化","社会","教育"]'::jsonb, 0, 'れきし ditulis 歴史, berarti sejarah.', 'Bab 41–45 · Mondai 2 No.14', 'kanji:歴史'),
  (41, 'draft', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'がいこくの <u>ぶんか</u>を しりたいです。', '["文化","歴史","社会","法律"]'::jsonb, 0, 'ぶんか ditulis 文化, berarti kebudayaan.', 'Bab 41–45 · Mondai 2 No.15', 'kanji:文化'),
  (41, 'draft', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ことしは しゅうにゅうが <u>へります</u>。', '["減ります","増えます","上がります","下がります"]'::jsonb, 0, 'へります ditulis 減ります, berarti menurun/berkurang.', 'Bab 41–45 · Mondai 2 No.16', 'kanji:減ります'),
  (41, 'draft', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'とても <u>しあわせな</u> かぞくです。', '["幸せな","丈夫な","変な","活発な"]'::jsonb, 0, 'しあわせな ditulis 幸せな, berarti bahagia.', 'Bab 41–45 · Mondai 2 No.17', 'kanji:幸せな'),
  (41, 'draft', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'えいがを みて <u>なみだ</u>が でました。', '["涙","空気","理由","順序"]'::jsonb, 0, 'なみだ ditulis 涙, berarti air mata.', 'Bab 41–45 · Mondai 2 No.18', 'kanji:涙'),
  (41, 'draft', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'おくれた <u>りゆう</u>を はなします。', '["理由","順序","表現","量"]'::jsonb, 0, 'りゆう ditulis 理由, berarti alasan.', 'Bab 41–45 · Mondai 2 No.19', 'kanji:理由'),
  (41, 'draft', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは ともだちを <u>しんじます</u>。', '["信じます","謝ります","眠ります","決めます"]'::jsonb, 0, 'しんじます ditulis 信じます, berarti percaya.', 'Bab 41–45 · Mondai 2 No.20', 'kanji:信じます'),
  (41, 'draft', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ごあんないします。</span><span class="arrange-chip"><b>②</b>あした</span><span class="arrange-chip"><b>③</b>かいじょう</span><span class="arrange-chip"><b>④</b>わたし</span><span class="arrange-chip"><b>⑤</b>を</span><span class="arrange-chip"><b>⑥</b>が</span></div><small>Petunjuk arti: “Besok saya akan memandu Anda ke tempat acara.”</small>', '["②→④→⑥→③→⑤→①","④→②→⑥→③→⑤→①","②→⑥→④→③→⑤→①","②→④→③→⑥→⑤→①"]'::jsonb, 0, 'Urutan yang benar: ②あした→④わたし→⑥が→③かいじょう→⑤を→①ごあんないします。 が menandai pelaku (diri sendiri) dalam kalimat merendahkan diri berpola ご～します seperti ごあんないします (Pel.41).', 'Bab 41–45 · Mondai 3 No.21', 'materi:book2:15:0'),
  (41, 'draft', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>の</span><span class="arrange-chip"><b>③</b>せんせい</span><span class="arrange-chip"><b>④</b>はいけんします。</span><span class="arrange-chip"><b>⑤</b>しりょう</span></div><small>Petunjuk arti: “Saya akan melihat dokumen milik guru.”</small>', '["③→②→⑤→①→④","②→③→⑤→①→④","③→⑤→②→①→④","③→②→①→⑤→④"]'::jsonb, 0, 'Urutan yang benar: ③せんせい→②の→⑤しりょう→①を→④はいけんします。 を menandai objek yang dilihat dengan 拝見します, bentuk rendah hati dari 見ます (Pel.41).', 'Bab 41–45 · Mondai 3 No.22', 'materi:book2:15:0'),
  (41, 'draft', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>は</span><span class="arrange-chip"><b>②</b>はやく</span><span class="arrange-chip"><b>③</b>いただきます。</span><span class="arrange-chip"><b>④</b>きょう</span><span class="arrange-chip"><b>⑤</b>かえらせて</span></div><small>Petunjuk arti: “Hari ini izinkan saya pulang lebih awal.”</small>', '["④→①→②→⑤→③","①→④→②→⑤→③","④→②→①→⑤→③","④→①→⑤→②→③"]'::jsonb, 0, 'Urutan yang benar: ④きょう→①は→②はやく→⑤かえらせて→③いただきます。 は menandai topik waktu sebelum pola ～させていただきます yang meminta izin dengan sopan (Pel.41).', 'Bab 41–45 · Mondai 3 No.23', 'materi:book2:15:0'),
  (41, 'draft', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>はたらく</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>にほん</span><span class="arrange-chip"><b>④</b>ために</span><span class="arrange-chip"><b>⑤</b>で</span><span class="arrange-chip"><b>⑥</b>にほんご</span><span class="arrange-chip"><b>⑦</b>べんきょうします。</span></div><small>Petunjuk arti: “Saya belajar bahasa Jepang untuk bekerja di Jepang.”</small>', '["③→⑤→①→④→⑥→②→⑦","⑤→③→①→④→⑥→②→⑦","③→①→⑤→④→⑥→②→⑦","③→⑤→④→①→⑥→②→⑦"]'::jsonb, 0, 'Urutan yang benar: ③にほん→⑤で→①はたらく→④ために→⑥にほんご→②を→⑦べんきょうします。 で menandai tempat berlangsungnya kegiatan はたらく, yang lalu diikuti ために untuk menyatakan tujuan yang disengaja (Pel.42).', 'Bab 41–45 · Mondai 3 No.24', 'materi:book2:16:0'),
  (41, 'draft', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ために</span><span class="arrange-chip"><b>②</b>けんこう</span><span class="arrange-chip"><b>③</b>あるきます。</span><span class="arrange-chip"><b>④</b>わたし</span><span class="arrange-chip"><b>⑤</b>の</span><span class="arrange-chip"><b>⑥</b>まいあさ</span><span class="arrange-chip"><b>⑦</b>は</span></div><small>Petunjuk arti: “Saya berjalan setiap pagi demi kesehatan.”</small>', '["④→⑦→②→⑤→①→⑥→③","⑦→④→②→⑤→①→⑥→③","④→②→⑦→⑤→①→⑥→③","④→⑦→⑤→②→①→⑥→③"]'::jsonb, 0, 'Urutan yang benar: ④わたし→⑦は→②けんこう→⑤の→①ために→⑥まいあさ→③あるきます。 の menghubungkan Kata Benda dengan ために pada pola Nのために untuk menyatakan tujuan/manfaat (Pel.42).', 'Bab 41–45 · Mondai 3 No.25', 'materi:book2:16:0'),
  (41, 'draft', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>わすれない</span><span class="arrange-chip"><b>②</b>メモします。</span><span class="arrange-chip"><b>③</b>ように</span><span class="arrange-chip"><b>④</b>てちょう</span><span class="arrange-chip"><b>⑤</b>に</span></div><small>Petunjuk arti: “Saya mencatat di buku agenda agar tidak lupa.”</small>', '["①→③→④→⑤→②","③→①→④→⑤→②","①→④→③→⑤→②","①→③→⑤→④→②"]'::jsonb, 0, 'Urutan yang benar: ①わすれない→③ように→④てちょう→⑤に→②メモします。 に menandai tempat tujuan penulisan pada メモします, sesudah anak kalimat ～ないように (Pel.42).', 'Bab 41–45 · Mondai 3 No.26', 'materi:book2:16:0'),
  (41, 'draft', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>だんだん</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>きました。</span><span class="arrange-chip"><b>④</b>なって</span><span class="arrange-chip"><b>⑤</b>この</span><span class="arrange-chip"><b>⑥</b>あつく</span><span class="arrange-chip"><b>⑦</b>まち</span></div><small>Petunjuk arti: “Kota ini lambat-laun mulai menjadi panas.”</small>', '["⑤→⑦→②→①→⑥→④→③","⑦→⑤→②→①→⑥→④→③","⑤→②→⑦→①→⑥→④→③","⑤→⑦→①→②→⑥→④→③"]'::jsonb, 0, 'Urutan yang benar: ⑤この→⑦まち→②は→①だんだん→⑥あつく→④なって→③きました。 は menandai topik kalimat, lalu ～てきます menyatakan perubahan yang berjalan sampai ke masa kini (Pel.43).', 'Bab 41–45 · Mondai 3 No.27', 'materi:book2:17:0'),
  (41, 'draft', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>にほんご</span><span class="arrange-chip"><b>②</b>いきます。</span><span class="arrange-chip"><b>③</b>べんきょうして</span><span class="arrange-chip"><b>④</b>を</span><span class="arrange-chip"><b>⑤</b>これからも</span></div><small>Petunjuk arti: “Mulai sekarang pun saya akan terus belajar bahasa Jepang.”</small>', '["⑤→①→④→③→②","①→⑤→④→③→②","⑤→④→①→③→②","⑤→①→③→④→②"]'::jsonb, 0, 'Urutan yang benar: ⑤これからも→①にほんご→④を→③べんきょうして→②いきます。 を menandai objek べんきょうして, dan ～ていきます menyatakan kegiatan yang berlanjut ke masa depan (Pel.43).', 'Bab 41–45 · Mondai 3 No.28', 'materi:book2:17:0'),
  (41, 'draft', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>いまにも</span><span class="arrange-chip"><b>②</b>あめ</span><span class="arrange-chip"><b>③</b>ふりそうです。</span><span class="arrange-chip"><b>④</b>は</span><span class="arrange-chip"><b>⑤</b>が</span><span class="arrange-chip"><b>⑥</b>きょう</span></div><small>Petunjuk arti: “Hari ini sepertinya sebentar lagi akan hujan.”</small>', '["⑥→④→①→②→⑤→③","④→⑥→①→②→⑤→③","⑥→①→④→②→⑤→③","⑥→④→②→①→⑤→③"]'::jsonb, 0, 'Urutan yang benar: ⑥きょう→④は→①いまにも→②あめ→⑤が→③ふりそうです。 が menandai subjek あめ sebelum ふりそうです, dugaan berdasarkan pengamatan sendiri (Pel.43).', 'Bab 41–45 · Mondai 3 No.29', 'materi:book2:17:0'),
  (41, 'draft', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ふる</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>で</span><span class="arrange-chip"><b>④</b>そうです。</span><span class="arrange-chip"><b>⑤</b>あめ</span><span class="arrange-chip"><b>⑥</b>てんきよほう</span><span class="arrange-chip"><b>⑦</b>が</span></div><small>Petunjuk arti: “Menurut ramalan cuaca, katanya akan hujan.”</small>', '["⑥→③→②→⑤→⑦→①→④","③→⑥→②→⑤→⑦→①→④","⑥→②→③→⑤→⑦→①→④","⑥→③→⑤→②→⑦→①→④"]'::jsonb, 0, 'Urutan yang benar: ⑥てんきよほう→③で→②は→⑤あめ→⑦が→①ふる→④そうです。 が menandai subjek あめ, lalu ふる＋そうです menyampaikan informasi yang didengar dari sumber lain (Pel.44).', 'Bab 41–45 · Mondai 3 No.30', 'materi:book2:18:0'),
  (41, 'draft', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>おくれている</span><span class="arrange-chip"><b>③</b>でんしゃ</span><span class="arrange-chip"><b>④</b>そうです。</span><span class="arrange-chip"><b>⑤</b>によると</span><span class="arrange-chip"><b>⑥</b>ニュース</span></div><small>Petunjuk arti: “Menurut berita, katanya kereta sedang terlambat.”</small>', '["⑥→⑤→③→①→②→④","⑤→⑥→③→①→②→④","⑥→③→⑤→①→②→④","⑥→⑤→①→③→②→④"]'::jsonb, 0, 'Urutan yang benar: ⑥ニュース→⑤によると→③でんしゃ→①が→②おくれている→④そうです。 Pola ～によると menyebutkan sumber informasi dan selalu berpasangan dengan そうです di akhir kalimat (Pel.44).', 'Bab 41–45 · Mondai 4 No.31', 'materi:book2:18:0'),
  (41, 'draft', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>あの</span><span class="arrange-chip"><b>②</b>がくせい</span><span class="arrange-chip"><b>③</b>ひと</span><span class="arrange-chip"><b>④</b>らしいです。</span><span class="arrange-chip"><b>⑤</b>は</span></div><small>Petunjuk arti: “Orang itu tampaknya mahasiswa.”</small>', '["①→③→⑤→②→④","③→①→⑤→②→④","①→⑤→③→②→④","①→③→②→⑤→④"]'::jsonb, 0, 'Urutan yang benar: ①あの→③ひと→⑤は→②がくせい→④らしいです。 らしいです menyatakan dugaan berdasarkan beberapa petunjuk, diletakkan langsung setelah Kata Benda (Pel.44).', 'Bab 41–45 · Mondai 4 No.32', 'materi:book2:18:0'),
  (41, 'draft', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>あした</span><span class="arrange-chip"><b>②</b>が</span><span class="arrange-chip"><b>③</b>じかん</span><span class="arrange-chip"><b>④</b>でんわします。</span><span class="arrange-chip"><b>⑤</b>あったら</span></div><small>Petunjuk arti: “Besok jika ada waktu, saya akan menelepon.”</small>', '["①→③→②→⑤→④","③→①→②→⑤→④","①→②→③→⑤→④","①→③→⑤→②→④"]'::jsonb, 0, 'Urutan yang benar: ①あした→③じかん→②が→⑤あったら→④でんわします。 Bentuk ～たら menyatakan syarat yang harus terjadi lebih dahulu sebelum hasilnya dilakukan (Pel.45).', 'Bab 41–45 · Mondai 4 No.33', 'materi:book2:19:0'),
  (41, 'draft', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ばあい</span><span class="arrange-chip"><b>②</b>おくれる</span><span class="arrange-chip"><b>③</b>れんらくして</span><span class="arrange-chip"><b>④</b>ください。</span><span class="arrange-chip"><b>⑤</b>は</span></div><small>Petunjuk arti: “Jika terlambat, tolong hubungi kami.”</small>', '["②→①→⑤→③→④","①→②→⑤→③→④","②→⑤→①→③→④","②→①→③→⑤→④"]'::jsonb, 0, 'Urutan yang benar: ②おくれる→①ばあい→⑤は→③れんらくして→④ください。 Pola ～場合は menyatakan kondisi secara formal, sering dipakai pada pengumuman resmi (Pel.45).', 'Bab 41–45 · Mondai 4 No.34', 'materi:book2:19:0'),
  (41, 'draft', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>のんだ</span><span class="arrange-chip"><b>②</b>なおりません。</span><span class="arrange-chip"><b>③</b>のに</span><span class="arrange-chip"><b>④</b>を</span><span class="arrange-chip"><b>⑤</b>くすり</span><span class="arrange-chip"><b>⑥</b>まいにち</span></div><small>Petunjuk arti: “Walaupun setiap hari minum obat, tidak kunjung sembuh.”</small>', '["⑥→⑤→④→①→③→②","⑤→⑥→④→①→③→②","⑥→④→⑤→①→③→②","⑥→⑤→①→④→③→②"]'::jsonb, 0, 'Urutan yang benar: ⑥まいにち→⑤くすり→④を→①のんだ→③のに→②なおりません。 のに menyatakan hasil yang BERLAWANAN dengan harapan, diletakkan setelah bentuk biasa のんだ (Pel.45).', 'Bab 41–45 · Mondai 4 No.35', 'materi:book2:19:0'),
  (41, 'draft', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'きょうは　わたしが　おきゃくさまを　ごあんないします。そのまえに、せんせいの　しりょうを　はいけんします。<br><small>「はいけんします」は、なにを　しますか。</small>', '["しりょうを みる","しりょうを みせる","しりょうを かす","しりょうを かりる"]'::jsonb, 0, '拝見します adalah bentuk RENDAH HATI dari 見ます (melihat), jadi sayalah yang MELIHAT dokumen — bukan 見せます (memperlihatkan kepada orang lain) (Pel.41).', 'Bab 41–45 · Soal Cerita No.36', 'materi:book2:15:0'),
  (41, 'draft', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'にほんで　はたらくために、まいにち　にほんごを　べんきょうします。あたらしい　ことばを　わすれないように、てちょうに　メモします。<br><small>メモするのは、なんのためですか。</small>', '["にほんで はたらくため","ことばを わすれないため","にほんごを おしえるため","てちょうを かうため"]'::jsonb, 1, 'ために (はたらくために) menyatakan tujuan yang DISENGAJA dan dapat dikendalikan, sedangkan ように (わすれないように) menyatakan tujuan berupa KEADAAN yang diharapkan terjadi — memo dibuat untuk yang kedua (Pel.42).', 'Bab 41–45 · Soal Cerita No.37', 'materi:book2:16:0'),
  (41, 'draft', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'にほんごが　だんだん　わかってきました。これからも　まいにち　べんきょうしていきます。<br><small>これから　さきも　つづける　ことは、なんですか。</small>', '["べんきょう","しごと","りょこう","うんどう"]'::jsonb, 0, '～ていきます menyatakan kegiatan yang BERLANJUT ke masa depan (terus belajar), berbeda dari ～てきます yang menyatakan perubahan dari masa lalu MENUJU sekarang (sudah mulai paham) (Pel.43).', 'Bab 41–45 · Soal Cerita No.38', 'materi:book2:17:0'),
  (41, 'draft', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'そらが　くらいですから、いまにも　あめが　ふりそうです。てんきよほうでは、あしたも　あめが　ふるそうです。<br><small>「ふるそうです」の　じょうほうは、どこから　きましたか。</small>', '["そらの ようす","てんきよほう","ともだちの はなし","しんぶん"]'::jsonb, 1, 'ふるそうです (bentuk biasa ＋ そうです) menyampaikan informasi yang DIDENGAR dari sumber lain, di sini ramalan cuaca; berbeda dari ふりそうです (Kata Kerja ます-stem ＋ そうです) yang merupakan dugaan dari PENGAMATAN SENDIRI atas langit yang gelap (Pel.43/44).', 'Bab 41–45 · Soal Cerita No.39', 'materi:book2:18:0'),
  (41, 'draft', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'きのうから　あたまが　いたいです。まいにち　くすりを　のんだのに、なおりません。じかんが　あったら、びょういんへ　いきます。<br><small>きたいと　ちがう　けっかに　なったのは、どの　ことですか。</small>', '["びょうきが なおらないこと","びょういんへ いくこと","じかんが あること","あたまが いたいこと"]'::jsonb, 0, 'のに menyatakan hasil yang BERLAWANAN dengan harapan (sudah minum obat tetapi tidak sembuh), sedangkan たら hanya menyatakan SYARAT yang belum tentu terjadi (jika ada waktu) (Pel.45).', 'Bab 41–45 · Soal Cerita No.40', 'materi:book2:19:0');
insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (41, 'published', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'せんせいを <u>呼びます</u>。', '["よびます","とりかえます","あずかります","たすけます"]'::jsonb, 0, '呼びます dibaca “よびます” dan berarti memanggil.', 'Bab 41–45 · Mondai 1 No.1', 'kanji:呼びます'),
  (41, 'published', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'くつしたを <u>取り替えます</u>。', '["とりかえます","よびます","あずかります","くらします"]'::jsonb, 0, '取り替えます dibaca “とりかえます” dan berarti mengganti.', 'Bab 41–45 · Mondai 1 No.2', 'kanji:取り替えます'),
  (41, 'published', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にもつを <u>預かります</u>。', '["あずかります","たすかります","たすけます","くらします"]'::jsonb, 0, '預かります dibaca “あずかります” dan berarti menjagakan/menerima titipan.', 'Bab 41–45 · Mondai 1 No.3', 'kanji:預かります'),
  (41, 'published', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'おくりものを <u>包みます</u>。', '["つつみます","まぜます","わかします","けいさんします"]'::jsonb, 0, '包みます dibaca “つつみます” dan berarti membungkus.', 'Bab 41–45 · Mondai 1 No.4', 'kanji:包みます'),
  (41, 'published', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'おゆを <u>沸かします</u>。', '["わかします","つつみます","まぜます","けいさんします"]'::jsonb, 0, '沸かします dibaca “わかします” dan berarti merebus/memanaskan air.', 'Bab 41–45 · Mondai 1 No.5', 'kanji:沸かします'),
  (41, 'published', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'かいいんが <u>増えます</u>。', '["ふえます","へります","あがります","さがります"]'::jsonb, 0, '増えます dibaca “ふえます” dan berarti meningkat/bertambah.', 'Bab 41–45 · Mondai 1 No.6', 'kanji:増えます'),
  (41, 'published', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'やまから いしが <u>落ちます</u>。', '["おちます","きれます","さがります","へります"]'::jsonb, 0, '落ちます dibaca “おちます” dan berarti jatuh.', 'Bab 41–45 · Mondai 1 No.7', 'kanji:落ちます'),
  (41, 'published', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもが <u>笑います</u>。', '["わらいます","なきます","かわきます","すべります"]'::jsonb, 0, '笑います dibaca “わらいます” dan berarti tertawa.', 'Bab 41–45 · Mondai 1 No.8', 'kanji:笑います'),
  (41, 'published', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ともだちに <u>謝ります</u>。', '["あやまります","しんじます","よういします","ねむります"]'::jsonb, 0, '謝ります dibaca “あやまります” dan berarti meminta maaf.', 'Bab 41–45 · Mondai 1 No.9', 'kanji:謝ります'),
  (41, 'published', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'よる はやく <u>眠ります</u>。', '["ねむります","あやまります","しんじます","なります"]'::jsonb, 0, '眠ります dibaca “ねむります” dan berarti tidur.', 'Bab 41–45 · Mondai 1 No.10', 'kanji:眠ります'),
  (41, 'published', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にほんの れきしに <u>きょうみ</u>が あります。', '["興味","情報","文法","発音"]'::jsonb, 0, 'きょうみ ditulis 興味, berarti minat.', 'Bab 41–45 · Mondai 2 No.11', 'kanji:興味'),
  (41, 'published', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ニュースで <u>じょうほう</u>を ききます。', '["情報","興味","文法","発音"]'::jsonb, 0, 'じょうほう ditulis 情報, berarti informasi.', 'Bab 41–45 · Mondai 2 No.12', 'kanji:情報'),
  (41, 'published', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんたくで <u>けいさんします</u>。', '["計算します","確認します","用意します","優勝します"]'::jsonb, 0, 'けいさんします ditulis 計算します, berarti menghitung.', 'Bab 41–45 · Mondai 2 No.13', 'kanji:計算します'),
  (41, 'published', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にほんの <u>れきし</u>を べんきょうします。', '["歴史","文化","社会","教育"]'::jsonb, 0, 'れきし ditulis 歴史, berarti sejarah.', 'Bab 41–45 · Mondai 2 No.14', 'kanji:歴史'),
  (41, 'published', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'がいこくの <u>ぶんか</u>を しりたいです。', '["文化","歴史","社会","法律"]'::jsonb, 0, 'ぶんか ditulis 文化, berarti kebudayaan.', 'Bab 41–45 · Mondai 2 No.15', 'kanji:文化'),
  (41, 'published', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ことしは しゅうにゅうが <u>へります</u>。', '["減ります","増えます","上がります","下がります"]'::jsonb, 0, 'へります ditulis 減ります, berarti menurun/berkurang.', 'Bab 41–45 · Mondai 2 No.16', 'kanji:減ります'),
  (41, 'published', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'とても <u>しあわせな</u> かぞくです。', '["幸せな","丈夫な","変な","活発な"]'::jsonb, 0, 'しあわせな ditulis 幸せな, berarti bahagia.', 'Bab 41–45 · Mondai 2 No.17', 'kanji:幸せな'),
  (41, 'published', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'えいがを みて <u>なみだ</u>が でました。', '["涙","空気","理由","順序"]'::jsonb, 0, 'なみだ ditulis 涙, berarti air mata.', 'Bab 41–45 · Mondai 2 No.18', 'kanji:涙'),
  (41, 'published', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'おくれた <u>りゆう</u>を はなします。', '["理由","順序","表現","量"]'::jsonb, 0, 'りゆう ditulis 理由, berarti alasan.', 'Bab 41–45 · Mondai 2 No.19', 'kanji:理由'),
  (41, 'published', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは ともだちを <u>しんじます</u>。', '["信じます","謝ります","眠ります","決めます"]'::jsonb, 0, 'しんじます ditulis 信じます, berarti percaya.', 'Bab 41–45 · Mondai 2 No.20', 'kanji:信じます'),
  (41, 'published', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ごあんないします。</span><span class="arrange-chip"><b>②</b>あした</span><span class="arrange-chip"><b>③</b>かいじょう</span><span class="arrange-chip"><b>④</b>わたし</span><span class="arrange-chip"><b>⑤</b>を</span><span class="arrange-chip"><b>⑥</b>が</span></div><small>Petunjuk arti: “Besok saya akan memandu Anda ke tempat acara.”</small>', '["②→④→⑥→③→⑤→①","④→②→⑥→③→⑤→①","②→⑥→④→③→⑤→①","②→④→③→⑥→⑤→①"]'::jsonb, 0, 'Urutan yang benar: ②あした→④わたし→⑥が→③かいじょう→⑤を→①ごあんないします。 が menandai pelaku (diri sendiri) dalam kalimat merendahkan diri berpola ご～します seperti ごあんないします (Pel.41).', 'Bab 41–45 · Mondai 3 No.21', 'materi:book2:15:0'),
  (41, 'published', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>の</span><span class="arrange-chip"><b>③</b>せんせい</span><span class="arrange-chip"><b>④</b>はいけんします。</span><span class="arrange-chip"><b>⑤</b>しりょう</span></div><small>Petunjuk arti: “Saya akan melihat dokumen milik guru.”</small>', '["③→②→⑤→①→④","②→③→⑤→①→④","③→⑤→②→①→④","③→②→①→⑤→④"]'::jsonb, 0, 'Urutan yang benar: ③せんせい→②の→⑤しりょう→①を→④はいけんします。 を menandai objek yang dilihat dengan 拝見します, bentuk rendah hati dari 見ます (Pel.41).', 'Bab 41–45 · Mondai 3 No.22', 'materi:book2:15:0'),
  (41, 'published', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>は</span><span class="arrange-chip"><b>②</b>はやく</span><span class="arrange-chip"><b>③</b>いただきます。</span><span class="arrange-chip"><b>④</b>きょう</span><span class="arrange-chip"><b>⑤</b>かえらせて</span></div><small>Petunjuk arti: “Hari ini izinkan saya pulang lebih awal.”</small>', '["④→①→②→⑤→③","①→④→②→⑤→③","④→②→①→⑤→③","④→①→⑤→②→③"]'::jsonb, 0, 'Urutan yang benar: ④きょう→①は→②はやく→⑤かえらせて→③いただきます。 は menandai topik waktu sebelum pola ～させていただきます yang meminta izin dengan sopan (Pel.41).', 'Bab 41–45 · Mondai 3 No.23', 'materi:book2:15:0'),
  (41, 'published', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>はたらく</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>にほん</span><span class="arrange-chip"><b>④</b>ために</span><span class="arrange-chip"><b>⑤</b>で</span><span class="arrange-chip"><b>⑥</b>にほんご</span><span class="arrange-chip"><b>⑦</b>べんきょうします。</span></div><small>Petunjuk arti: “Saya belajar bahasa Jepang untuk bekerja di Jepang.”</small>', '["③→⑤→①→④→⑥→②→⑦","⑤→③→①→④→⑥→②→⑦","③→①→⑤→④→⑥→②→⑦","③→⑤→④→①→⑥→②→⑦"]'::jsonb, 0, 'Urutan yang benar: ③にほん→⑤で→①はたらく→④ために→⑥にほんご→②を→⑦べんきょうします。 で menandai tempat berlangsungnya kegiatan はたらく, yang lalu diikuti ために untuk menyatakan tujuan yang disengaja (Pel.42).', 'Bab 41–45 · Mondai 3 No.24', 'materi:book2:16:0'),
  (41, 'published', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ために</span><span class="arrange-chip"><b>②</b>けんこう</span><span class="arrange-chip"><b>③</b>あるきます。</span><span class="arrange-chip"><b>④</b>わたし</span><span class="arrange-chip"><b>⑤</b>の</span><span class="arrange-chip"><b>⑥</b>まいあさ</span><span class="arrange-chip"><b>⑦</b>は</span></div><small>Petunjuk arti: “Saya berjalan setiap pagi demi kesehatan.”</small>', '["④→⑦→②→⑤→①→⑥→③","⑦→④→②→⑤→①→⑥→③","④→②→⑦→⑤→①→⑥→③","④→⑦→⑤→②→①→⑥→③"]'::jsonb, 0, 'Urutan yang benar: ④わたし→⑦は→②けんこう→⑤の→①ために→⑥まいあさ→③あるきます。 の menghubungkan Kata Benda dengan ために pada pola Nのために untuk menyatakan tujuan/manfaat (Pel.42).', 'Bab 41–45 · Mondai 3 No.25', 'materi:book2:16:0'),
  (41, 'published', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>わすれない</span><span class="arrange-chip"><b>②</b>メモします。</span><span class="arrange-chip"><b>③</b>ように</span><span class="arrange-chip"><b>④</b>てちょう</span><span class="arrange-chip"><b>⑤</b>に</span></div><small>Petunjuk arti: “Saya mencatat di buku agenda agar tidak lupa.”</small>', '["①→③→④→⑤→②","③→①→④→⑤→②","①→④→③→⑤→②","①→③→⑤→④→②"]'::jsonb, 0, 'Urutan yang benar: ①わすれない→③ように→④てちょう→⑤に→②メモします。 に menandai tempat tujuan penulisan pada メモします, sesudah anak kalimat ～ないように (Pel.42).', 'Bab 41–45 · Mondai 3 No.26', 'materi:book2:16:0'),
  (41, 'published', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>だんだん</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>きました。</span><span class="arrange-chip"><b>④</b>なって</span><span class="arrange-chip"><b>⑤</b>この</span><span class="arrange-chip"><b>⑥</b>あつく</span><span class="arrange-chip"><b>⑦</b>まち</span></div><small>Petunjuk arti: “Kota ini lambat-laun mulai menjadi panas.”</small>', '["⑤→⑦→②→①→⑥→④→③","⑦→⑤→②→①→⑥→④→③","⑤→②→⑦→①→⑥→④→③","⑤→⑦→①→②→⑥→④→③"]'::jsonb, 0, 'Urutan yang benar: ⑤この→⑦まち→②は→①だんだん→⑥あつく→④なって→③きました。 は menandai topik kalimat, lalu ～てきます menyatakan perubahan yang berjalan sampai ke masa kini (Pel.43).', 'Bab 41–45 · Mondai 3 No.27', 'materi:book2:17:0'),
  (41, 'published', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>にほんご</span><span class="arrange-chip"><b>②</b>いきます。</span><span class="arrange-chip"><b>③</b>べんきょうして</span><span class="arrange-chip"><b>④</b>を</span><span class="arrange-chip"><b>⑤</b>これからも</span></div><small>Petunjuk arti: “Mulai sekarang pun saya akan terus belajar bahasa Jepang.”</small>', '["⑤→①→④→③→②","①→⑤→④→③→②","⑤→④→①→③→②","⑤→①→③→④→②"]'::jsonb, 0, 'Urutan yang benar: ⑤これからも→①にほんご→④を→③べんきょうして→②いきます。 を menandai objek べんきょうして, dan ～ていきます menyatakan kegiatan yang berlanjut ke masa depan (Pel.43).', 'Bab 41–45 · Mondai 3 No.28', 'materi:book2:17:0'),
  (41, 'published', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>いまにも</span><span class="arrange-chip"><b>②</b>あめ</span><span class="arrange-chip"><b>③</b>ふりそうです。</span><span class="arrange-chip"><b>④</b>は</span><span class="arrange-chip"><b>⑤</b>が</span><span class="arrange-chip"><b>⑥</b>きょう</span></div><small>Petunjuk arti: “Hari ini sepertinya sebentar lagi akan hujan.”</small>', '["⑥→④→①→②→⑤→③","④→⑥→①→②→⑤→③","⑥→①→④→②→⑤→③","⑥→④→②→①→⑤→③"]'::jsonb, 0, 'Urutan yang benar: ⑥きょう→④は→①いまにも→②あめ→⑤が→③ふりそうです。 が menandai subjek あめ sebelum ふりそうです, dugaan berdasarkan pengamatan sendiri (Pel.43).', 'Bab 41–45 · Mondai 3 No.29', 'materi:book2:17:0'),
  (41, 'published', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ふる</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>で</span><span class="arrange-chip"><b>④</b>そうです。</span><span class="arrange-chip"><b>⑤</b>あめ</span><span class="arrange-chip"><b>⑥</b>てんきよほう</span><span class="arrange-chip"><b>⑦</b>が</span></div><small>Petunjuk arti: “Menurut ramalan cuaca, katanya akan hujan.”</small>', '["⑥→③→②→⑤→⑦→①→④","③→⑥→②→⑤→⑦→①→④","⑥→②→③→⑤→⑦→①→④","⑥→③→⑤→②→⑦→①→④"]'::jsonb, 0, 'Urutan yang benar: ⑥てんきよほう→③で→②は→⑤あめ→⑦が→①ふる→④そうです。 が menandai subjek あめ, lalu ふる＋そうです menyampaikan informasi yang didengar dari sumber lain (Pel.44).', 'Bab 41–45 · Mondai 3 No.30', 'materi:book2:18:0'),
  (41, 'published', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>おくれている</span><span class="arrange-chip"><b>③</b>でんしゃ</span><span class="arrange-chip"><b>④</b>そうです。</span><span class="arrange-chip"><b>⑤</b>によると</span><span class="arrange-chip"><b>⑥</b>ニュース</span></div><small>Petunjuk arti: “Menurut berita, katanya kereta sedang terlambat.”</small>', '["⑥→⑤→③→①→②→④","⑤→⑥→③→①→②→④","⑥→③→⑤→①→②→④","⑥→⑤→①→③→②→④"]'::jsonb, 0, 'Urutan yang benar: ⑥ニュース→⑤によると→③でんしゃ→①が→②おくれている→④そうです。 Pola ～によると menyebutkan sumber informasi dan selalu berpasangan dengan そうです di akhir kalimat (Pel.44).', 'Bab 41–45 · Mondai 4 No.31', 'materi:book2:18:0'),
  (41, 'published', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>あの</span><span class="arrange-chip"><b>②</b>がくせい</span><span class="arrange-chip"><b>③</b>ひと</span><span class="arrange-chip"><b>④</b>らしいです。</span><span class="arrange-chip"><b>⑤</b>は</span></div><small>Petunjuk arti: “Orang itu tampaknya mahasiswa.”</small>', '["①→③→⑤→②→④","③→①→⑤→②→④","①→⑤→③→②→④","①→③→②→⑤→④"]'::jsonb, 0, 'Urutan yang benar: ①あの→③ひと→⑤は→②がくせい→④らしいです。 らしいです menyatakan dugaan berdasarkan beberapa petunjuk, diletakkan langsung setelah Kata Benda (Pel.44).', 'Bab 41–45 · Mondai 4 No.32', 'materi:book2:18:0'),
  (41, 'published', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>あした</span><span class="arrange-chip"><b>②</b>が</span><span class="arrange-chip"><b>③</b>じかん</span><span class="arrange-chip"><b>④</b>でんわします。</span><span class="arrange-chip"><b>⑤</b>あったら</span></div><small>Petunjuk arti: “Besok jika ada waktu, saya akan menelepon.”</small>', '["①→③→②→⑤→④","③→①→②→⑤→④","①→②→③→⑤→④","①→③→⑤→②→④"]'::jsonb, 0, 'Urutan yang benar: ①あした→③じかん→②が→⑤あったら→④でんわします。 Bentuk ～たら menyatakan syarat yang harus terjadi lebih dahulu sebelum hasilnya dilakukan (Pel.45).', 'Bab 41–45 · Mondai 4 No.33', 'materi:book2:19:0'),
  (41, 'published', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ばあい</span><span class="arrange-chip"><b>②</b>おくれる</span><span class="arrange-chip"><b>③</b>れんらくして</span><span class="arrange-chip"><b>④</b>ください。</span><span class="arrange-chip"><b>⑤</b>は</span></div><small>Petunjuk arti: “Jika terlambat, tolong hubungi kami.”</small>', '["②→①→⑤→③→④","①→②→⑤→③→④","②→⑤→①→③→④","②→①→③→⑤→④"]'::jsonb, 0, 'Urutan yang benar: ②おくれる→①ばあい→⑤は→③れんらくして→④ください。 Pola ～場合は menyatakan kondisi secara formal, sering dipakai pada pengumuman resmi (Pel.45).', 'Bab 41–45 · Mondai 4 No.34', 'materi:book2:19:0'),
  (41, 'published', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>のんだ</span><span class="arrange-chip"><b>②</b>なおりません。</span><span class="arrange-chip"><b>③</b>のに</span><span class="arrange-chip"><b>④</b>を</span><span class="arrange-chip"><b>⑤</b>くすり</span><span class="arrange-chip"><b>⑥</b>まいにち</span></div><small>Petunjuk arti: “Walaupun setiap hari minum obat, tidak kunjung sembuh.”</small>', '["⑥→⑤→④→①→③→②","⑤→⑥→④→①→③→②","⑥→④→⑤→①→③→②","⑥→⑤→①→④→③→②"]'::jsonb, 0, 'Urutan yang benar: ⑥まいにち→⑤くすり→④を→①のんだ→③のに→②なおりません。 のに menyatakan hasil yang BERLAWANAN dengan harapan, diletakkan setelah bentuk biasa のんだ (Pel.45).', 'Bab 41–45 · Mondai 4 No.35', 'materi:book2:19:0'),
  (41, 'published', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'きょうは　わたしが　おきゃくさまを　ごあんないします。そのまえに、せんせいの　しりょうを　はいけんします。<br><small>「はいけんします」は、なにを　しますか。</small>', '["しりょうを みる","しりょうを みせる","しりょうを かす","しりょうを かりる"]'::jsonb, 0, '拝見します adalah bentuk RENDAH HATI dari 見ます (melihat), jadi sayalah yang MELIHAT dokumen — bukan 見せます (memperlihatkan kepada orang lain) (Pel.41).', 'Bab 41–45 · Soal Cerita No.36', 'materi:book2:15:0'),
  (41, 'published', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'にほんで　はたらくために、まいにち　にほんごを　べんきょうします。あたらしい　ことばを　わすれないように、てちょうに　メモします。<br><small>メモするのは、なんのためですか。</small>', '["にほんで はたらくため","ことばを わすれないため","にほんごを おしえるため","てちょうを かうため"]'::jsonb, 1, 'ために (はたらくために) menyatakan tujuan yang DISENGAJA dan dapat dikendalikan, sedangkan ように (わすれないように) menyatakan tujuan berupa KEADAAN yang diharapkan terjadi — memo dibuat untuk yang kedua (Pel.42).', 'Bab 41–45 · Soal Cerita No.37', 'materi:book2:16:0'),
  (41, 'published', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'にほんごが　だんだん　わかってきました。これからも　まいにち　べんきょうしていきます。<br><small>これから　さきも　つづける　ことは、なんですか。</small>', '["べんきょう","しごと","りょこう","うんどう"]'::jsonb, 0, '～ていきます menyatakan kegiatan yang BERLANJUT ke masa depan (terus belajar), berbeda dari ～てきます yang menyatakan perubahan dari masa lalu MENUJU sekarang (sudah mulai paham) (Pel.43).', 'Bab 41–45 · Soal Cerita No.38', 'materi:book2:17:0'),
  (41, 'published', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'そらが　くらいですから、いまにも　あめが　ふりそうです。てんきよほうでは、あしたも　あめが　ふるそうです。<br><small>「ふるそうです」の　じょうほうは、どこから　きましたか。</small>', '["そらの ようす","てんきよほう","ともだちの はなし","しんぶん"]'::jsonb, 1, 'ふるそうです (bentuk biasa ＋ そうです) menyampaikan informasi yang DIDENGAR dari sumber lain, di sini ramalan cuaca; berbeda dari ふりそうです (Kata Kerja ます-stem ＋ そうです) yang merupakan dugaan dari PENGAMATAN SENDIRI atas langit yang gelap (Pel.43/44).', 'Bab 41–45 · Soal Cerita No.39', 'materi:book2:18:0'),
  (41, 'published', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'きのうから　あたまが　いたいです。まいにち　くすりを　のんだのに、なおりません。じかんが　あったら、びょういんへ　いきます。<br><small>きたいと　ちがう　けっかに　なったのは、どの　ことですか。</small>', '["びょうきが なおらないこと","びょういんへ いくこと","じかんが あること","あたまが いたいこと"]'::jsonb, 0, 'のに menyatakan hasil yang BERLAWANAN dengan harapan (sudah minum obat tetapi tidak sembuh), sedangkan たら hanya menyatakan SYARAT yang belum tentu terjadi (jika ada waktu) (Pel.45).', 'Bab 41–45 · Soal Cerita No.40', 'materi:book2:19:0');
